ag_no_cache();ag_require_admin();header('X-Robots-Tag: noindex, nofollow');
try {
    $scope=is_string($_GET['scope'] ?? null)?$_GET['scope']:'admin';if(!in_array($scope,array('admin','user','public','designer'),true))throw new RuntimeException('Unsupported preview area.');
    $state=ag_sa_read();$brand=$state['branding'];$theme=ag_sd_active_theme($state,$scope);
    if(isset($_GET['theme']))$theme=ag_sa_library($state)[$_GET['theme']] ?? null;
    if(isset($_GET['design'])){$draft=ag_sd_import_get($_GET['design']);$theme=$draft['themes'][$scope] ?? null;$brand=$draft['branding'];}
    if(isset($_GET['history'])){$entry=ag_sd_history_get($_GET['history']);$theme=ag_sd_active_theme($entry['after'],$scope);$brand=$entry['after']['branding'];}
    if(!$theme)throw new RuntimeException('Theme not found.');$identity=ag_sd_identity($brand);
}catch(Throwable $e){http_response_code(404);exit(ag_h($e->getMessage()));}
